<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-4"><h1 class="h3"><?= esc($title) ?></h1><a class="btn btn-outline-secondary" href="<?= url_to('admin.packages') ?>">Back</a></div><form method="post" enctype="multipart/form-data" action="<?= $package?site_url('admin/packages/'.$package['id']):url_to('admin.packages') ?>"><?= csrf_field() ?><?php if($package): ?><input type="hidden" name="_method" value="PUT"><?php endif ?><div class="card border-0 p-4 mb-3"><div class="row g-3"><div class="col-md-8"><label class="form-label">Package Name</label><input class="form-control" name="name" value="<?= esc(old('name',$package['name']??'')) ?>" required></div><div class="col-md-4"><label class="form-label">Package Code</label><input class="form-control" value="<?= esc($package['package_code']??'Generated after save') ?>" readonly></div><div class="col-md-6"><label class="form-label">Slug</label><input class="form-control" name="slug" value="<?= esc(old('slug',$package['slug']??'')) ?>"></div><div class="col-md-3"><label class="form-label">Package Price</label><input class="form-control" type="number" step=".01" min="0" name="package_price" value="<?= esc(old('package_price',$package['package_price']??0)) ?>" required></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['draft','active','inactive'] as $s): ?><option value="<?= $s ?>" <?= old('status',$package['status']??'draft')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Image</label><input class="form-control" type="file" name="main_image" accept="image/jpeg,image/png,image/webp"></div><div class="col-md-3"><label class="form-label">Sort Order</label><input class="form-control" type="number" name="sort_order" value="<?= esc(old('sort_order',$package['sort_order']??0)) ?>"></div><div class="col-md-3 d-flex align-items-end"><label class="form-check"><input class="form-check-input" type="checkbox" name="featured" value="1" <?= old('featured',$package['featured']??0)?'checked':'' ?>> Featured</label></div><div class="col-12"><label class="form-label">Short Description</label><textarea class="form-control" name="short_description"><?= esc(old('short_description',$package['short_description']??'')) ?></textarea></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="5" name="description"><?= esc(old('description',$package['description']??'')) ?></textarea></div></div></div><div class="card border-0 p-4 mb-3"><h2 class="h5">Package Components</h2><div class="table-responsive"><table class="table" id="itemTable"><thead><tr><th>Product</th><th>Variant</th><th>Qty</th><th></th></tr></thead><tbody><?php foreach($items as $i=>$item): ?><?= view('admin/packages/item_row',compact('i','item','products','variants')) ?><?php endforeach ?></tbody></table></div><button class="btn btn-outline-success" type="button" id="addItem">Add Product</button><hr><div class="row"><div class="col-md-4"><strong>Regular Total:</strong> ৳<?= number_format((float)($package['regular_total']??0),2) ?></div><div class="col-md-4"><strong>Savings:</strong> ৳<?= number_format(max(0,(float)($package['regular_total']??0)-(float)($package['package_price']??0)),2) ?></div><div class="col-md-4"><strong>Available:</strong> <?= $available>=999999?'Unlimited':$available ?></div></div></div><div class="card border-0 p-4 mb-3"><h2 class="h5">SEO</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">SEO Title</label><input class="form-control" name="seo_title" value="<?= esc(old('seo_title',$package['seo_title']??'')) ?>"></div><div class="col-md-6"><label class="form-label">Meta Description</label><textarea class="form-control" name="seo_description"><?= esc(old('seo_description',$package['seo_description']??'')) ?></textarea></div></div></div><button class="btn btn-success">Save Package</button></form><template id="itemTemplate"><?= view('admin/packages/item_row',['i'=>'__INDEX__','item'=>[],'products'=>$products,'variants'=>$variants]) ?></template><script>document.getElementById('addItem').addEventListener('click',()=>{const b=document.querySelector('#itemTable tbody');b.insertAdjacentHTML('beforeend',document.getElementById('itemTemplate').innerHTML.replaceAll('__INDEX__',b.children.length));});document.addEventListener('click',e=>{if(e.target.matches('.remove-item'))e.target.closest('tr').remove();});</script><?= $this->endSection() ?>
